CREATE OR REPLACE FUNCTION set_reservation_delete_after() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE v_tz text; BEGIN SELECT r.timezone INTO v_tz FROM restaurants r WHERE r.id=NEW.restaurant_id; NEW.delete_after:=((NEW.starts_at AT TIME ZONE coalesce(v_tz,'Europe/Berlin'))::date+30); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION set_pickup_order_delete_after() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE v_tz text; BEGIN SELECT r.timezone INTO v_tz FROM restaurants r WHERE r.id=NEW.restaurant_id; NEW.delete_after:=((NEW.ready_at AT TIME ZONE coalesce(v_tz,'Europe/Berlin'))::date+30); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION set_callback_delete_after() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE v_tz text; BEGIN SELECT r.timezone INTO v_tz FROM restaurants r WHERE r.id=NEW.restaurant_id; NEW.delete_after:=((coalesce(NEW.handled_at,NEW.created_at) AT TIME ZONE coalesce(v_tz,'Europe/Berlin'))::date+14); RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_reservations_delete_after ON reservations; CREATE TRIGGER trg_reservations_delete_after BEFORE INSERT OR UPDATE OF starts_at,restaurant_id ON reservations FOR EACH ROW EXECUTE FUNCTION set_reservation_delete_after();
DROP TRIGGER IF EXISTS trg_pickup_orders_delete_after ON pickup_orders; CREATE TRIGGER trg_pickup_orders_delete_after BEFORE INSERT OR UPDATE OF ready_at,restaurant_id ON pickup_orders FOR EACH ROW EXECUTE FUNCTION set_pickup_order_delete_after();
DROP TRIGGER IF EXISTS trg_callback_requests_delete_after ON callback_requests; CREATE TRIGGER trg_callback_requests_delete_after BEFORE INSERT OR UPDATE OF handled_at,created_at,restaurant_id ON callback_requests FOR EACH ROW EXECUTE FUNCTION set_callback_delete_after();
